const menu=document.querySelector('.menu');const nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Menu sluiten':'Menu openen');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Menu openen')}));
const examples={intake:['“Ik wil mijn badkamer renoveren.”','Een slim formulier vraagt naar de ruimte, timing en gewenste werken.','Van losse info naar een helder overzicht.','De antwoorden worden geordend in een bruikbare projectsamenvatting.','Jij start het gesprek met een voorsprong.','Minder heen-en-weer. Meteen de juiste vragen.'],vragen:['“Hoe verloopt een eerste afspraak?”','Een bezoeker stelt een vraag over jouw dienstverlening.','Een antwoord op basis van jouw informatie.','Een slimme assistent gebruikt jouw goedgekeurde uitleg en verwijst bij twijfel naar jou.','Je klant vindt sneller de juiste informatie.','Jij houdt meer ruimte voor vragen die je aandacht nodig hebben.'],opvolging:['Een nieuwe aanvraag komt binnen.','Een potentiële klant deelt contactgegevens en een concrete vraag.','Alle informatie op de juiste plek.','Een koppeling zet de aanvraag in je overzicht en maakt een conceptantwoord klaar.','Jij controleert en neemt persoonlijk contact op.','Geen losse aanvragen meer zoeken tussen verschillende tools.']};const keys=['flow-one','flow-one-text','flow-two','flow-two-text','flow-result','flow-result-text'];const tabs=[...document.querySelectorAll('[data-use]')];function activate(tab){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1});keys.forEach((key,i)=>document.getElementById(key).textContent=examples[tab.dataset.use][i]);document.getElementById('use-panel').setAttribute('aria-labelledby',tab.id)}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activate(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowDown'||e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowUp'||e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();activate(tabs[n]);tabs[n].focus()}})});document.querySelectorAll('[data-interest]').forEach(a=>a.addEventListener('click',()=>document.getElementById('interest').value=a.dataset.interest));document.getElementById('year').textContent=new Date().getFullYear();document.getElementById('contact-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);document.getElementById('request-text').value=`Hallo Lorenz,\n\nMijn naam is ${data.get('name')}${data.get('business')?' van '+data.get('business'):''}.\nIk heb interesse in: ${data.get('interest')}.\n\n${data.get('message')}`;document.getElementById('request-output').hidden=false;document.getElementById('form-status').textContent='Je aanvraag staat klaar. Er is niets verstuurd.';document.getElementById('request-text').focus()});document.getElementById('copy-request').addEventListener('click',async()=>{const field=document.getElementById('request-text');try{await navigator.clipboard.writeText(field.value);document.getElementById('form-status').textContent='Aanvraag gekopieerd. Er is niets verstuurd.'}catch{field.focus();field.select();document.getElementById('form-status').textContent='Selecteer en kopieer de tekst van je aanvraag.'}});
document.querySelectorAll('[data-package]').forEach(a=>a.addEventListener('click',()=>{const label=a.dataset.package;document.getElementById('interest').value=label.includes('Onderhoud')?'Maandelijks onderhoud':label.includes('maatwerk')?'AI en automatisering':'Een nieuwe website';const field=document.getElementById('message');const line='Ik heb interesse in '+label+'.';if(!field.value.includes(line))field.value=line+(field.value?'\n\n'+field.value:'')}));document.getElementById('download-request').addEventListener('click',()=>{const blob=new Blob([document.getElementById('request-text').value],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='mijn-aanvraag-lk-webdesign.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('form-status').textContent='Je aanvraag is als tekstbestand klaargezet om te downloaden. Er is niets verstuurd.'});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Menu openen');menu.focus()}});
